const path=a=>a.image.split('/').slice(-2).join('/');const card=a=>`<article class="card"><a href="${path(a)}" data-zoom="${a.id}"><img loading="lazy" src="${path(a)}" alt="${esc(a.title)}"></a><div class="tag">${a.id} / ${(a.section_part_ids||[]).join(', ')}</div><h3>${esc(a.title.replace(/([a-z])([A-Z])/g,'$1 $2'))}</h3><p class="small">${esc(a.brief)}</p><a href="../../prompts/${a.id}.txt">Saved generation prompt</a></article>`;
function bindZoom(){document.querySelectorAll('[data-zoom]').forEach(a=>a.onclick=e=>{e.preventDefault();const j=DATA.art.find(j=>j.id===a.dataset.zoom);$('#viewImage').src=path(j);$('#viewTitle').textContent=' '+j.id+' / '+j.title;$('#viewer').showModal()})}
$('#assemblyGrid').innerHTML=DATA.art.filter(a=>!a.section_part_ids.length).map(card).join('');
function drawArt(){const q=$('#artSearch').value.toLowerCase();const items=DATA.art.filter(a=>a.section_part_ids.length&&JSON.stringify(a).toLowerCase().includes(q));$('#artCount').textContent=items.length+' modeling sheets shown';$('#artGrid').innerHTML=items.map(card).join('');bindZoom()}
function drawParts(){const q=$('#partSearch').value.toLowerCase(),role=$('#role').value;filtered=DATA.parts.filter(p=>(!role||p.role===role)&&JSON.stringify(p).toLowerCase().includes(q));$('#partCount').textContent=filtered.length+' components shown';$('#rows').innerHTML=filtered.map(p=>`<tr><td><b>${p.id}</b> ${esc(p.name)}<p><a href="${path(DATA.art.find(a=>a.id===p.model_sheet))}">${p.model_sheet} visual reference</a></p></td><td>${p.role}<p class="small">Shared family: ${p.shared_asset||'section-specific'}</p></td><td>${Object.values(p.dimensions_cm).join(' × ')} cm<p class="small">${esc(p.dimension_basis)}</p></td><td>${p.materials.join(', ')}<p>${esc(p.notes)}</p><details><summary>Blender prompt & pivot</summary><p>${esc(p.pivot)}</p><textarea readonly>${esc(p.blender_brief)}</textarea><a href="briefs/${p.id}_${p.name}.md">Individual file</a></details></td></tr>`).join('')}
$('#close').onclick=()=>$('#viewer').close();$('#artSearch').oninput=drawArt;$('#partSearch').oninput=drawParts;$('#role').onchange=drawParts;$('#export').onclick=()=>{const b=new Blob([JSON.stringify(filtered,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='ChainCrossing-Sluice-Blender-briefs.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};drawArt();drawParts();
